# Demonstrating common Python exceptions and their causes:

# 1. TypeError: Incompatible types for an operation
def show_type_error():
    try:
        res = "Score: " + 100
    except TypeError as e:
        print("1. TypeError:", e)

# 2. ValueError: Valid type, but inappropriate content
def show_value_error():
    try:
        num = int("abc")
    except ValueError as e:
        print("2. ValueError:", e)

# 3. IndexError: Accessing beyond sequence boundaries
def show_index_error():
    items = ["alpha", "beta"]
    try:
        item = items[5]
    except IndexError as e:
        print("3. IndexError:", e)

# 4. KeyError: Accessing a missing dictionary key
def show_key_error():
    student = {"name": "Kavi", "age": 19}
    try:
        grade = student["grade"]
    except KeyError as e:
        print("4. KeyError:", e)

show_type_error()
show_value_error()
show_index_error()
show_key_error()

# Simulating a multi-level function call to examine traceback flow
def level_c(divisor):
    # Root cause occurs here on division by zero:
    return 100 / divisor

def level_b(step_val):
    return level_c(step_val)

def level_a(init_val):
    return level_b(init_val)

print("Simulating function call chain: level_a -> level_b -> level_c")
try:
    level_a(0)
except ZeroDivisionError as err:
    import traceback
    print("\n--- CAPTURED TRACEBACK ---")
    traceback.print_exc(limit=3)
    print("--- DIAGNOSIS STRATEGY ---")
    print("1. Read bottom line first: ZeroDivisionError: division by zero")
    print("2. Read the line above: level_c(divisor) -> 100 / divisor")
    print("3. Inspect call hierarchy: level_a -> level_b -> level_c")
